-- Sentetik Taş Bilgi Kütüphanesi makaleleri
INSERT INTO public.stone_knowledge_articles (id, tenant_id, title, content, category, sub_category, tags, related_stones, related_minerals, source, keyword, is_active)
VALUES
  ('de5a0021-c11e-4000-8000-000000000001'::uuid, '40f842a0-e3e8-448c-8971-9a938e1faccb'::uuid, 'Mohs Sertlik Ölçeği ve Taşların Dayanıklılığı', 'Mohs ölçeği, minerallerin birbirini çizebilme özelliğine göre 1 ile 10 arasında sıralandığı göreceli bir sertlik ölçeğidir.

Selenit (2) tırnakla çizilebilecek kadar yumuşakken kuvars ailesindeki ametist ve sitrin (7) günlük kullanıma oldukça dayanıklıdır. Florit (4) gibi orta sertlikteki taşlar darbelere karşı korunmalıdır.

Uygulamada sertlik; taşın cepte taşınabilirliğini, birlikte saklanabileceği taşları ve temizlik yöntemini belirlemede ilk bakılacak bilgidir.

Not: Bu makale Yaşam Sistemi vitrin hesabı için hazırlanmış SENTETİK örnek içeriktir; tıbbi tavsiye değildir.', 'Mineroloji', 'Temel Bilgiler', ARRAY['mohs', 'sertlik', 'dayanıklılık']::text[], ARRAY['AMETİST', 'SELENİT', 'FLORİT']::text[], ARRAY['SİLİSYUM', 'KALSİYUM']::text[], 'Vitrin örnek içeriği', 'mohs sertlik', true),
  ('de5a0021-c11e-4000-8000-000000000002'::uuid, '40f842a0-e3e8-448c-8971-9a938e1faccb'::uuid, 'Doğaltaşların Temizlenmesi ve Saklanması', 'Her taş aynı yöntemle temizlenmez. Selenit suda çözünür; malahit ve pirit nemden etkilenir. Bu taşlar kuru bir fırça veya yumuşak bezle temizlenmelidir.

Ametist, sitrin ve pembe kuvars gibi renkli kuvarslar uzun süre doğrudan güneşte kaldığında solabilir. Taşları ayrı keselerde saklamak, sert taşların yumuşakları çizmesini önler.

Temizlik sonrasında taşın kayıt kartındaki ''Bakım'' alanına uygulanan yöntemi not etmek, danışan çalışmalarında tutarlılık sağlar.

